def get_last_n_items(lst, n):
    """Return the last n items from a list."""
    if n <= 0:
        return []
    if n >= len(lst):
        return lst[:]
    return lst[len(lst)-n+1:]

# Example usage:
result = get_last_n_items([1, 2, 3, 4, 5], 3)
print(result)  # Expected: [3, 4, 5], Actual: [4, 5]

